// Flatten the response into fields that read well in the execution log and in
// whatever alert channel this ends up feeding.
const res = $input.first().json;
const body = res.body || {};
const failed = (body.checks || []).filter(c => c.status === 'fail');
return [{ json: {
  trustworthy: res.statusCode === 200,
  statusCode: res.statusCode,
  verdict: body.verdict || 'UNKNOWN',
  destination: body.destination || null,
  rowsInSheet: body.counts?.sheet ?? null,
  rowsInExport: body.counts?.truth ?? null,
  failures: failed.map(c => `${c.id}: ${c.headline}`),
} }];

// Where a Slack, email or ticket node goes. Kept as code so this workflow
// imports and runs without any credentials configured.
const j = $input.first().json;
console.log(`ALERT — ${j.verdict} (HTTP ${j.statusCode})`);
console.log(`  sheet ${j.rowsInSheet} rows vs export ${j.rowsInExport} rows`);
for (const f of j.failures) console.log(`  · ${f}`);
return [{ json: { alerted: true, ...j } }];
